var body = root.querySelector('.pf2-holds-body');
var rows = Array.prototype.slice.call(body.querySelectorAll('.pf2-holds-row'));
var sorters = Array.prototype.slice.call(root.querySelectorAll('.pf2-holds-sort'));
var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var max = 0;
rows.forEach(function (r) { max = Math.max(max, Math.abs(parseFloat(r.getAttribute('data-w')))); });
rows.forEach(function (r, i) {
  var f = r.querySelector('.pf2-holds-fill');
  var w = (parseFloat(r.getAttribute('data-w')) / max * 100).toFixed(1) + '%';
  if (reduce) { f.style.width = w; return; }
  f.style.transitionDelay = (i * 55) + 'ms';
  requestAnimationFrame(function () { f.style.width = w; });
});
var state = { key: 'w', dir: -1 };
var litTimer = null;
function apply() {
  var sorted = rows.slice().sort(function (a, b) {
    var av = parseFloat(a.getAttribute('data-' + state.key));
    var bv = parseFloat(b.getAttribute('data-' + state.key));
    return (av - bv) * state.dir;
  });
  sorted.forEach(function (r) { body.appendChild(r); });
  sorters.forEach(function (btn) {
    var on = btn.getAttribute('data-key') === state.key;
    btn.classList.toggle('pf2-holds-sort-on', on);
    btn.classList.toggle('pf2-holds-asc', on && state.dir === 1);
    var th = btn.parentNode;
    th.setAttribute('aria-sort', on ? (state.dir === 1 ? 'ascending' : 'descending') : 'none');
  });
  if (reduce) return;
  rows.forEach(function (r) { r.classList.add('pf2-holds-lit'); });
  if (litTimer) clearTimeout(litTimer);
  litTimer = setTimeout(function () {
    rows.forEach(function (r) { r.classList.remove('pf2-holds-lit'); });
  }, 90);
}
sorters.forEach(function (btn) {
  btn.addEventListener('click', function () {
    var k = btn.getAttribute('data-key');
    if (state.key === k) { state.dir = state.dir * -1; } else { state.key = k; state.dir = -1; }
    apply();
  });
});

