var plot = root.querySelector('.pf2-cume-plot');
var svg = root.querySelector('.pf2-cume-svg');
var pline = root.querySelector('.pf2-cume-pline');
var cross = root.querySelector('.pf2-cume-cross');
var dp = root.querySelector('.pf2-cume-dotp');
var db = root.querySelector('.pf2-cume-dotb');
