var bline = root.querySelector('.pf2-cume-bline');
var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
function parse(el) {
  return el.getAttribute('points').trim().split(/\s+/).map(function (s) {
    var a = s.split(','); return { x: parseFloat(a[0]), y: parseFloat(a[1]) };
  });
}
var pts = parse(pline), bpts = parse(bline);
var P = [0,3.1,5.4,4.2,7.8,9.6,8.1,11.4,14.9,13.2,16.8,19.5,22.1,20.4,24.6,27.9,25.3,29.8,32.4,30.1,33.7,35.2,34.1,36.8,38.4];
