  var L = pline.getTotalLength();
  pline.style.transition = 'none';
  pline.style.strokeDasharray = L + ' ' + L;
  pline.style.strokeDashoffset = L;
  pline.getBoundingClientRect();
  pline.style.transition = 'stroke-dashoffset 1.05s cubic-bezier(.3,.9,.3,1)';
