var rows = Array.prototype.slice.call(root.querySelectorAll('.pf2-drift-row'));
var act = root.querySelector('.pf2-drift-act');
var flag = root.querySelector('.pf2-drift-flag');
var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var SCALE = 4;
var flat = false;
function paint(zero) {
  rows.forEach(function (r, i) {
    var d = parseFloat(r.getAttribute('data-d'));
    var bar = r.querySelector('.pf2-drift-bar');
    var val = r.querySelector('.pf2-drift-val');
    var v = zero ? 0 : d;
    var half = Math.min(Math.abs(v) / SCALE * 50, 50);
    bar.style.width = half.toFixed(1) + '%';
    bar.style.left = (v >= 0 ? 50 : 50 - half).toFixed(1) + '%';
    if (!reduce) bar.style.transitionDelay = (i * 45) + 'ms';
    if (zero) {
      val.textContent = '— 0.0';
    } else {
      val.textContent = (d >= 0 ? '▲ +' : '▼ -') + Math.abs(d).toFixed(1);
    }
  });
  root.classList.toggle('pf2-drift-flat', !!zero);
  flag.textContent = zero ? 'All in band' : '2 out of band';
  flag.classList.toggle('pf2-drift-ok', !!zero);
  act.textContent = zero ? 'Undo' : 'Rebalance';
}
rows.forEach(function (r) {
  var bar = r.querySelector('.pf2-drift-bar');
  bar.style.width = '0%';
  bar.style.left = '50%';
});
requestAnimationFrame(function () { paint(false); });
act.addEventListener('click', function () { flat = !flat; paint(flat); });

