var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var rows = Array.prototype.slice.call(root.querySelectorAll('.pf2-watch-row'));
var pulse = root.querySelector('.pf2-watch-pulse');
Array.prototype.slice.call(root.querySelectorAll('.pf2-watch-star')).forEach(function (b) {
  b.addEventListener('click', function () {
    var on = b.getAttribute('aria-pressed') === 'true';
    b.setAttribute('aria-pressed', on ? 'false' : 'true');
    b.classList.toggle('pf2-watch-pin', !on);
    var sym = b.parentNode.querySelector('.pf2-watch-sym').textContent;
    b.setAttribute('aria-label', (on ? 'Pin ' : 'Unpin ') + sym);
  });
});
var books = rows.map(function (r) {
  var line = r.querySelector('.pf2-watch-line');
  var ys = line.getAttribute('points').trim().split(/\s+/).map(function (p) { return parseFloat(p.split(',')[1]); });
  return {
    el: r, line: line, ys: ys,
    px: parseFloat(r.getAttribute('data-px')),
    base: parseFloat(r.getAttribute('data-base')),
    pxEl: r.querySelector('.pf2-watch-px'),
    chgEl: r.querySelector('.pf2-watch-chg')
  };
});
if (!reduce) {
  var on = false;
  var tp = setInterval(function () {
    if (!root.isConnected) { clearInterval(tp); return; }
    on = !on;
    pulse.classList.toggle('pf2-watch-dim', on);
  }, 850);
  var tt = setInterval(function () {
    if (!root.isConnected) { clearInterval(tt); return; }
    var b = books[Math.floor(Math.random() * books.length)];
    var step = (Math.random() - 0.48) * (b.px * 0.0022);
    var next = Math.max(0.01, b.px + step);
    var up = next >= b.px;
    b.px = next;
    b.pxEl.textContent = next.toFixed(2);
    b.pxEl.classList.remove('pf2-watch-fup', 'pf2-watch-fdn');
    void b.pxEl.offsetWidth;
    b.pxEl.classList.add(up ? 'pf2-watch-fup' : 'pf2-watch-fdn');
    setTimeout(function () { b.pxEl.classList.remove('pf2-watch-fup', 'pf2-watch-fdn'); }, 60);
    var last = b.ys[b.ys.length - 1];
    var ny = Math.max(3, Math.min(19, last - step / (b.px * 0.0022) * 1.3));
    b.ys.shift(); b.ys.push(ny);
    b.line.setAttribute('points', b.ys.map(function (y, i) { return (i * 4) + ',' + y.toFixed(1); }).join(' '));
    var pct = (b.px / b.base - 1) * 100;
    var rising = pct >= 0;
    b.chgEl.textContent = (rising ? '▲ +' : '▼ -') + Math.abs(pct).toFixed(2) + '%';
    b.chgEl.classList.toggle('pf2-watch-up', rising);
    b.chgEl.classList.toggle('pf2-watch-down', !rising);
    b.line.classList.toggle('pf2-watch-lup', rising);
    b.line.classList.toggle('pf2-watch-ldn', !rising);
  }, 1700);
}

