  '6M': { d: 61340, p: 8.45, note: 'vs 6M ago', bars: [30,36,34,42,48,44,52,58,56,64,72,80] },
  '1Y': { d: 121880, p: 18.32, note: 'vs 1Y ago', bars: [18,24,20,28,34,30,42,48,44,56,66,80] },
  'ALL': { d: 402610, p: 104.42, note: 'since 2019', bars: [8,14,12,22,30,26,38,50,46,60,70,84] }
};
var tabs = Array.prototype.slice.call(root.querySelectorAll('.pf2-nw-tab'));
var thumb = root.querySelector('.pf2-nw-thumb');
var arrow = root.querySelector('.pf2-nw-arrow');
var abs = root.querySelector('.pf2-nw-abs');
var pct = root.querySelector('.pf2-nw-pct');
var per = root.querySelector('.pf2-nw-per');
var fills = Array.prototype.slice.call(root.querySelectorAll('.pf2-nw-barf'));
var shown = 0, raf = null, cur = '6M';
function money(n) {
  var s = n < 0 ? '-' : '+';
