  var from = shown, t0 = null;
  function step(t) {
    if (t0 === null) t0 = t;
    var k = Math.min(1, (t - t0) / 550);
    var e = 1 - Math.pow(1 - k, 3);
    shown = from + (to - from) * e;
    abs.textContent = money(shown);
    if (k < 1) { raf = requestAnimationFrame(step); } else { shown = to; abs.textContent = money(to); }
  }
  raf = requestAnimationFrame(step);
}
