  thumb.style.width = btn.offsetWidth + 'px';
  thumb.style.transform = 'translateX(' + (btn.offsetLeft - 2) + 'px)';
}
function set(k) {
  cur = k;
  var d = data[k];
  root.classList.toggle('pf2-nw-neg', d.d < 0);
  arrow.textContent = d.d < 0 ? '▼' : '▲';
  pct.textContent = (d.p < 0 ? '-' : '+') + Math.abs(d.p).toFixed(1) + '%';
  per.textContent = d.note;
  tween(d.d);
  fills.forEach(function (f, i) {
    if (!reduce) f.style.transitionDelay = (i * 22) + 'ms';
    f.style.height = d.bars[i] + '%';
