  statusEl.textContent = out ? (out + ' sleeve' + (out > 1 ? 's' : '') + ' out · trade $' + cash + 'k') : 'All sleeves in policy · 0.0pp';
}
items.forEach(function (o) { o.bar.style.width = '0%'; });
function draw(f) { items.forEach(function (o) { place(o, o.d0 * f); }); status(f); }
