var applied = false, raf = 0;
btn.addEventListener('click', function () {
  var to = applied ? 1 : 0, from = applied ? 0 : 1;
  applied = !applied;
  btn.textContent = applied ? 'Undo' : 'Rebalance';
  if (applied) { root.classList.add('pf2-drift-v2--done'); } else { root.classList.remove('pf2-drift-v2--done'); }
