var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var N = 30;
var items = Array.prototype.slice.call(root.querySelectorAll('.pf2-watchspark__row')).map(function (el) {
  var px = parseFloat(el.getAttribute('data-px'));
  var vol = parseFloat(el.getAttribute('data-vol'));
  var chg = parseFloat(el.getAttribute('data-chg'));
  var s = parseInt(el.getAttribute('data-seed'), 10) || 1;
  var base = px / (1 + chg / 100);
  var arr = [], v = base, i;
  for (i = 0; i < N; i++) {
    s = (s * 1103515245 + 12345) % 2147483648;
    v += (s / 2147483648 - 0.48) * vol + (px - base) / N;
    arr.push(v);
  }
  arr[N - 1] = px;
  return { el: el, arr: arr, px: px, base: base, vol: vol, seed: s,
    ln: el.querySelector('.pf2-watchspark__ln'), pxEl: el.querySelector('.pf2-watchspark__px'), chgEl: el.querySelector('.pf2-watchspark__chg') };
});
function draw(o) {
  var lo = Math.min.apply(null, o.arr), hi = Math.max.apply(null, o.arr), sp = (hi - lo) || 1;
  var pts = '', i;
  for (i = 0; i < o.arr.length; i++) {
    pts += (i / (o.arr.length - 1) * 60).toFixed(2) + ',' + (18 - (o.arr[i] - lo) / sp * 16).toFixed(2) + ' ';
  }
  o.ln.setAttribute('points', pts.trim());
  var up = o.px >= o.base;
  if (up) { o.ln.classList.remove('pf2-watchspark__ln--dn'); } else { o.ln.classList.add('pf2-watchspark__ln--dn'); }
}
function render(o, dir) {
  var chg = (o.px / o.base - 1) * 100;
  var up = chg >= 0;
  o.pxEl.textContent = o.px.toFixed(2);
  o.chgEl.textContent = (up ? '▲ ' : '▼ ') + Math.abs(chg).toFixed(2) + '%';
  o.chgEl.classList.toggle('pf2-watchspark__chg--up', up);
  o.chgEl.classList.toggle('pf2-watchspark__chg--dn', !up);
  draw(o);
  if (dir) {
    o.pxEl.classList.remove('pf2-watchspark__px--up', 'pf2-watchspark__px--dn');
    void o.pxEl.offsetWidth;
    o.pxEl.classList.add(dir > 0 ? 'pf2-watchspark__px--up' : 'pf2-watchspark__px--dn');
  }
}
items.forEach(function (o) { render(o, 0); });
items.forEach(function (o) {
  o.el.addEventListener('click', function () {
    var on = o.el.classList.toggle('pf2-watchspark__row--sel');
    o.el.setAttribute('aria-pressed', on ? 'true' : 'false');
    items.forEach(function (p) {
      if (p !== o) { p.el.classList.remove('pf2-watchspark__row--sel'); p.el.setAttribute('aria-pressed', 'false'); }
    });
  });
});
if (!reduce) {
  var timer = window.setInterval(function () {
    if (!root.isConnected) { window.clearInterval(timer); return; }
    if (document.hidden) { return; }
    var o = items[Math.floor(Math.random() * items.length)];
    o.seed = (o.seed * 1103515245 + 12345) % 2147483648;
    var d = (o.seed / 2147483648 - 0.5) * o.vol * 0.9;
    if (Math.abs(d) < o.vol * 0.06) { d = o.vol * 0.1; }
    o.px = Math.round((o.px + d) * 100) / 100;
    o.arr.push(o.px); o.arr.shift();
    render(o, d > 0 ? 1 : -1);
  }, 2400);
}

