css:
.pf2-networth{--pf2nw-tx:#E8EBF4;--pf2nw-mu:#8992A9;--pf2nw-up:#33D69F;--pf2nw-dn:#FF6F6F;--pf2nw-ac:#5B8DEF;--pf2nw-i:0;box-sizing:border-box;width:100%;max-width:340px;padding:10px 12px 11px;border:1px solid rgba(255,255,255,.09);border-radius:14px;background:linear-gradient(160deg,#141826,#0E111A);color:var(--pf2nw-tx);font-family:ui-sans-serif,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;font-variant-numeric:tabular-nums;-webkit-font-smoothing:antialiased}
.pf2-networth__head{display:flex;align-items:baseline;justify-content:space-between;gap:8px}
.pf2-networth__lab{font-size:10px;letter-spacing:.09em;text-transform:uppercase;color:var(--pf2nw-mu)}
.pf2-networth__asof{font-size:9px;color:#6E7688}
.pf2-networth__val{margin-top:3px;font-size:21px;font-weight:680;letter-spacing:-.025em;line-height:1.1}
.pf2-networth__figure{margin-top:1px}
.pf2-networth__chg{display:flex;align-items:baseline;gap:5px;font-size:11px;font-weight:640}
.pf2-networth__chg--up{color:var(--pf2nw-up)}
.pf2-networth__chg--dn{color:var(--pf2nw-dn)}
.pf2-networth__arw{font-size:9px}
.pf2-networth__pct{opacity:.85}
.pf2-networth__from{margin-top:1px;font-size:9px;letter-spacing:.03em;color:#6E7688}
.pf2-networth__figure--flip{animation:pf2-networth-flip .34s cubic-bezier(.2,.8,.3,1)}
.pf2-networth__bars{display:flex;align-items:flex-end;gap:2px;height:26px;margin:7px 0 8px}
.pf2-networth__bar{flex:1 1 0;min-width:0;height:8%;border-radius:1.5px;background:var(--pf2nw-ac);opacity:.45;transition:height .55s cubic-bezier(.22,.75,.3,1),opacity .3s ease}
.pf2-networth__bar--last{opacity:1}
.pf2-networth__seg{position:relative;display:flex;gap:0;padding:2px;border-radius:8px;background:rgba(255,255,255,.05)}
.pf2-networth__pill{position:absolute;top:2px;bottom:2px;left:2px;width:calc((100% - 4px)/5);border-radius:6px;background:rgba(255,255,255,.13);transform:translateX(calc(var(--pf2nw-i) * 100%));transition:transform .32s cubic-bezier(.3,.9,.3,1)}
.pf2-networth__tab{position:relative;box-sizing:border-box;flex:1 1 0;min-width:0;padding:4px 0;border:0;border-radius:6px;background:transparent;color:#98A0B3;font:inherit;font-size:9.5px;font-weight:600;letter-spacing:.04em;cursor:pointer;transition:color .16s ease}
.pf2-networth__tab:hover{color:#DCE2EF}
.pf2-networth__tab:focus-visible{outline:2px solid #7FA6FF;outline-offset:2px}
.pf2-networth__tab--on{color:#F1F4FB}
@keyframes pf2-networth-flip{0%{opacity:0;transform:translateY(5px)}100%{opacity:1;transform:none}}
@media (prefers-reduced-motion:reduce){.pf2-networth__bar,.pf2-networth__pill{transition:none}.pf2-networth__figure--flip{animation:none}}

